3115	struct ProjectEvidenceBoardItem: Identifiable {
3116	    let id: UUID
3117	    let name: String
3118	    let entries: [(link: ProjectLink, record: HistoryRecord)]
3119	
3120	    var sortedEntries: [(link: ProjectLink, record: HistoryRecord)] {
3121	        entries.sorted { lhs, rhs in
3122	            if lhs.record.draft.date == rhs.record.draft.date {
3123	                return lhs.link.updatedAt > rhs.link.updatedAt
3124	            }
3125	            return lhs.record.draft.date > rhs.record.draft.date
3126	        }
3127	    }
3128	
3129	    var confirmedCount: Int {
3130	        entries.filter(\.link.isUserConfirmed).count
3131	    }
3132	
3133	    var evidenceCount: Int {
3134	        entries.count
3135	    }
3136	
3137	    var latestDate: Date {
3138	        sortedEntries.first?.record.draft.date ?? .distantPast
3139	    }
3140	
3141	    var latestRecord: HistoryRecord? {
3142	        sortedEntries.first?.record
3143	    }
3144	
3145	    var digest: ProjectEvidenceDigest {
3146	        ProjectEvidenceDigest(projectId: id, evidence: entries)
3147	    }
3148	
3149	    var dominantType: ProjectLinkType {
3150	        let counts = Dictionary(grouping: entries.map(\.link.linkType), by: { $0 })
3151	            .mapValues(\.count)
3152	        return counts.max { lhs, rhs in
3153	            lhs.value == rhs.value ? lhs.key.title < rhs.key.title : lhs.value < rhs.value
3154	        }?.key ?? .evidence
3155	    }
3156	
3157	    var statusLabel: String {
3158	        if confirmedCount > 0 {
3159	            return "\(confirmedCount) 条已确认"
3160	        }
3161	        return "待确认"
3162	    }
3163	
3164	    var typeSummary: String {
3165	        let types = Array(Set(entries.map(\.link.linkType)))
3166	            .sorted { $0.title < $1.title }
3167	            .prefix(3)
3168	            .map(\.title)
3169	        return types.isEmpty ? "证据" : types.joined(separator: " / ")
3170	    }
3171	
3172	    func record(containing link: ProjectLink) -> HistoryRecord? {
3173	        entries.first { $0.link.id == link.id }?.record
3174	    }
3175	}
3176	
3177	func projectStatusFilteredItems(
3178	    _ items: [ProjectEvidenceBoardItem],
3179	    projectsById: [UUID: Project],
3180	    status: ProjectStatus?
3181	) -> [ProjectEvidenceBoardItem] {
3182	    guard let status else { return items }
3183	    return items.filter { item in
3184	        guard let project = projectsById[item.id] else { return false }
3185	        return project.status == status
3186	    }
